const deadline = Date.parse('2026-10-22T09:02:27.028Z');
let killed=false;
const end=Date.now()+45000;
while(Date.now()<end){
  const s=sdk.getState();
  const duck=s.nearbyNpcs.filter(n=>/^duck$/i.test(n.name)).sort((a,b)=>a.distance-b.distance)[0];
  if(!duck){ killed=true; break; }
  const r=await bot.attack(duck);
  if(!r.success){ await sdk.waitForTicks(2); continue; }
  await sdk.waitForCondition(st=>{const n=st.nearbyNpcs.find(x=>x.index===duck.index);return !n||n.hp===0;},8000).then(()=>{}).catch(()=>{});
}
const s2=sdk.getState();
console.log('duckKilled', killed, 'rem', ((deadline-Date.now())/60000).toFixed(2), 'hp', s2.player.hp);
console.log('ducksNow', s2.nearbyNpcs.filter(n=>/^duck$/i.test(n.name)).length);
await sdk.dm('Alpha','Ranged the ducks over water with shortbow - got Duck!');
